using Nockx.Base.CryptographyTypes.MlDsa;

namespace Nockx.BaseTest.MlDsaPublicKeyTests;

public class ConstructionTests {
	[Fact]
	public void ConstructSuccess() => new MlDsaPublicKey(Convert.FromBase64String(""));

	[Fact]
	public void ConstructInvalidDataFail() => Assert.Throws<InvalidOperationException>(() => new MlDsaPublicKey(Convert.FromBase64String("")));

	[Fact]
	public void ConstructIncorrectKeyTypeFail() => Assert.Equal("Public ML-DSA-65 key was attempted to be created with RSA key data", Assert.Throws<InvalidOperationException>(() => new MlDsaPublicKey(Convert.FromBase64String(""))).Message);
}